def execute_code(language, code, input=None, timeout=None, memoryLimit=None, enableNetworking=None, **_extra):
    import json, os, datetime, time, re, subprocess, tempfile, sys, traceback

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _day_bucket_iso():
        n = datetime.datetime.now(datetime.timezone.utc)
        d = datetime.datetime(n.year, n.month, n.day, tzinfo=datetime.timezone.utc)
        return d.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        r = (ms << 80) | int.from_bytes(os.urandom(10), "big")
        out = []
        for _ in range(26):
            out.append(alphabet[r & 31])
            r >>= 5
        return f"{prefix}_{''.join(reversed(out))}"

    def _find_active_cap_profile(profiles):
        actives = [p for p in profiles if isinstance(p, dict) and p.get("status") == "active"]
        if actives:
            actives.sort(key=lambda x: (x.get("updated_at") or "", x.get("created_at") or ""), reverse=True)
            return actives[0]
        return None

    def _select_key(keys):
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None
        candidates.sort(key=lambda x: (x.get("last_used_at") or "", x.get("updated_at") or "", x.get("created_at") or ""), reverse=True)
        return candidates[0]

    def _validate_number(name, v, int_like=True):
        if v is None:
            return None
        if isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a number")
        if not isinstance(v, (int, float)):
            return _err("VALIDATION_ERROR", f"{name} must be a number")
        if int_like and isinstance(v, float) and not v.is_integer():
            return _err("VALIDATION_ERROR", f"{name} must be an integer")
        iv = int(v)
        return iv

    def _safe_run_python(src, stdin_text, timeout_s):
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "main.py")
            with open(path, "w", encoding="utf-8") as f:
                f.write(src)
            cmd = [sys.executable, "-I", "-S", "-u", path]
            try:
                p = subprocess.run(
                    cmd,
                    input=(stdin_text if stdin_text is not None else ""),
                    text=True,
                    capture_output=True,
                    timeout=timeout_s
                )
                return {
                    "status": "completed",
                    "exit_code": p.returncode,
                    "stdout": p.stdout,
                    "stderr": p.stderr
                }
            except subprocess.TimeoutExpired as e:
                out = ""
                err = ""
                try:
                    out = e.stdout if isinstance(e.stdout, str) else (e.stdout.decode("utf-8", "replace") if e.stdout else "")
                    err = e.stderr if isinstance(e.stderr, str) else (e.stderr.decode("utf-8", "replace") if e.stderr else "")
                except Exception:
                    pass
                return {
                    "status": "timeout",
                    "exit_code": None,
                    "stdout": out,
                    "stderr": err
                }

    def _safe_run_js(src, stdin_text, timeout_s):
        # Best-effort: requires a local node binary. If missing, fail gracefully.
        node = None
        for cand in ("node", "nodejs"):
            if shutil_which(cand):
                node = cand
                break
        if node is None:
            return {"status": "no_runtime", "exit_code": None, "stdout": "", "stderr": "JavaScript runtime not available (node not found)"}
        wrapper = (
            "const fs=require('fs');\n"
            "let input='';\n"
            "try{input=fs.readFileSync(0,'utf8');}catch(e){}\n"
            "globalThis.__stdin=input;\n"
            "(async()=>{\n"
            "try{\n"
            + src + "\n"
            "}catch(e){\n"
            "console.error(String(e&&e.stack?e.stack:e)); process.exitCode=1;\n"
            "}\n"
            "})();\n"
        )
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "main.js")
            with open(path, "w", encoding="utf-8") as f:
                f.write(wrapper)
            cmd = [node, path]
            try:
                p = subprocess.run(
                    cmd,
                    input=(stdin_text if stdin_text is not None else ""),
                    text=True,
                    capture_output=True,
                    timeout=timeout_s
                )
                return {
                    "status": "completed",
                    "exit_code": p.returncode,
                    "stdout": p.stdout,
                    "stderr": p.stderr
                }
            except subprocess.TimeoutExpired as e:
                out = ""
                err = ""
                try:
                    out = e.stdout if isinstance(e.stdout, str) else (e.stdout.decode("utf-8", "replace") if e.stdout else "")
                    err = e.stderr if isinstance(e.stderr, str) else (e.stderr.decode("utf-8", "replace") if e.stderr else "")
                except Exception:
                    pass
                return {
                    "status": "timeout",
                    "exit_code": None,
                    "stdout": out,
                    "stderr": err
                }

    def shutil_which(cmd):
        # local helper to avoid global import contract
        import os
        path = os.environ.get("PATH", "")
        exts = [""] if os.name != "nt" else os.environ.get("PATHEXT", "").split(os.pathsep)
        for p in path.split(os.pathsep):
            p = p.strip('"')
            for ext in exts:
                c = os.path.join(p, cmd + ext)
                if os.path.isfile(c) and os.access(c, os.X_OK):
                    return c
        return None

    # Load store
    keys = _load("api_keys.json")
    profiles = _load("capability_profiles.json")
    exec_reqs = _load("execution_requests.json")
    counters = _load("usage_counters.json")

    # Resolve auth context (ambient)
    api_key = _select_key(keys)
    cap = _find_active_cap_profile(profiles)
    if api_key is None or cap is None:
        return _err("UNAUTHORIZED", "No active API key and capability profile combination available")

    # Rate limit check (per minute across all tools)
    try:
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        rl = int(api_key.get("rate_limit_per_min", 1) or 1)
        recent = 0
        for r in exec_reqs:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != api_key.get("id"):
                continue
            ts = r.get("requested_at") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts_dt >= minute_ago:
                recent += 1
        for v in _load("code_validations.json"):
            if not isinstance(v, dict): 
                continue
            if v.get("api_key_id") != api_key.get("id"):
                continue
            ts = v.get("requested_at") or v.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts_dt >= minute_ago:
                recent += 1
        if recent >= rl:
            return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        return _err("RATE_LIMIT", "Rate limit check failed")

    # Validate inputs
    if language not in ("javascript", "python"):
        return _err("VALIDATION_ERROR", "Unsupported language")
    if not isinstance(code, str) or not code.strip():
        return _err("VALIDATION_ERROR", "code must be a non-empty string")
    if input is not None and not isinstance(input, str):
        return _err("VALIDATION_ERROR", "input must be a string")
    if enableNetworking is not None and not isinstance(enableNetworking, bool):
        return _err("VALIDATION_ERROR", "enableNetworking must be a boolean")

    tmo = _validate_number("timeout", timeout, int_like=True)
    if isinstance(tmo, dict) and "error" in tmo:
        return tmo
    mem = _validate_number("memoryLimit", memoryLimit, int_like=True)
    if isinstance(mem, dict) and "error" in mem:
        return mem

    # Compute effective limits
    svc_max_tmo = int(cap.get("max_timeout_ms", 60000) or 60000)
    svc_max_mem = int(cap.get("max_memory_mb", 512) or 512)
    key_max_tmo = int(api_key.get("max_timeout_ms", 60000) or 60000)
    key_def_tmo = int(api_key.get("default_timeout_ms", 1000) or 1000)
    key_max_mem = int(api_key.get("max_memory_mb", 512) or 512)
    key_def_mem = int(api_key.get("default_memory_mb", 128) or 128)

    if tmo is None:
        eff_tmo = key_def_tmo
    else:
        eff_tmo = min(int(tmo), key_max_tmo, svc_max_tmo, 60000)
    if eff_tmo < 1 or eff_tmo > 60000:
        return _err("VALIDATION_ERROR", "timeout out of range")

    if mem is None:
        eff_mem = key_def_mem
    else:
        eff_mem = min(int(mem), key_max_mem, svc_max_mem, 512)
    if eff_mem < 1 or eff_mem > 512:
        return _err("VALIDATION_ERROR", "memoryLimit out of range")

    req_enable_net = bool(enableNetworking) if enableNetworking is not None else False
    net_supported = bool(cap.get("networking_supported", False))
    key_allows_net = bool(api_key.get("allow_networking", False))

    now_iso = _now()
    req_id = _gen_id("creq")
    row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "tool_name": "execute_code",
        "language": language,
        "code": code,
        "stdin": input if input is not None else None,
        "variables_raw": None,
        "variables_json": None,
        "timeout_ms": eff_tmo,
        "memory_limit_mb": eff_mem,
        "enable_networking": req_enable_net,
        "status": "queued",
        "reject_reason": None,
        "reject_details": None,
        "exit_code": None,
        "stdout": None,
        "stderr": None,
        "error_type": None,
        "error_message": None,
        "duration_ms": None,
        "billed_units": 1,
        "requested_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Upsert usage counter at ingress (execute_count++)
    day_iso = _day_bucket_iso()
    ctr = None
    for c in counters:
        if isinstance(c, dict) and c.get("api_key_id") == api_key["id"] and c.get("day") == day_iso:
            ctr = c
            break
    if ctr is None:
        ctr = {
            "id": _gen_id("cruc"),
            "api_key_id": api_key["id"],
            "day": day_iso,
            "execute_count": 0,
            "validate_count": 0,
            "execution_ms_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        counters.append(ctr)
    ctr["execute_count"] = int(ctr.get("execute_count", 0) or 0) + 1
    ctr["updated_at"] = now_iso

    # Networking policy rejection at ingress
    if req_enable_net and (not net_supported or not key_allows_net):
        row["status"] = "rejected"
        row["reject_reason"] = "networking_not_allowed"
        row["finished_at"] = now_iso
        row["updated_at"] = now_iso
        exec_reqs.append(row)
        _save("usage_counters.json", counters)
        _save("execution_requests.json", exec_reqs)
        return {
            "execution_request": row,
            "result": None,
            "meta": {
                "latency_ms": int((time.time() - t0) * 1000)
            }
        }

    # Quota & key status gate before queued->running
    if api_key.get("status") != "active":
        row["status"] = "rejected"
        row["reject_reason"] = "quota_exceeded"
        row["reject_details"] = {"reason": "api_key_inactive"}
        row["finished_at"] = now_iso
        row["updated_at"] = now_iso
        exec_reqs.append(row)
        _save("usage_counters.json", counters)
        _save("execution_requests.json", exec_reqs)
        return {
            "execution_request": row,
            "result": None,
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    daily_limit = int(api_key.get("daily_exec_limit", 0) or 0)
    if daily_limit >= 0 and int(ctr.get("execute_count", 0) or 0) > daily_limit:
        row["status"] = "rejected"
        row["reject_reason"] = "quota_exceeded"
        row["finished_at"] = now_iso
        row["updated_at"] = now_iso
        exec_reqs.append(row)
        _save("usage_counters.json", counters)
        _save("execution_requests.json", exec_reqs)
        return {
            "execution_request": row,
            "result": None,
            "meta": {"latency_ms": int((time.time() - t0) * 1000)}
        }

    # Transition queued -> running
    row["status"] = "running"
    row["started_at"] = _now()
    row["updated_at"] = row["started_at"]
    exec_reqs.append(row)
    _save("usage_counters.json", counters)
    _save("execution_requests.json", exec_reqs)

    # Execute
    start = time.time()
    timeout_s = max(0.001, eff_tmo / 1000.0)
    if req_enable_net:
        # We cannot actually enable networking in this offline runner; treat as policy violation at runtime.
        run = {"status": "completed", "exit_code": 1, "stdout": "", "stderr": "Networking not available in offline runner"}
        status = "failed"
        err_type = "security_error"
        err_msg = "networking_unavailable"
    else:
        if language == "python":
            run = _safe_run_python(code, input, timeout_s)
        else:
            run = _safe_run_js(code, input, timeout_s)

        status = None
        err_type = None
        err_msg = None
        if run["status"] == "timeout":
            status = "timed_out"
            err_type = "runtime_error"
            err_msg = "timed_out"
        elif run["status"] == "no_runtime":
            status = "failed"
            err_type = "runtime_error"
            err_msg = "runtime_unavailable"
        else:
            status = "succeeded" if (run.get("exit_code") == 0) else "failed"
            if status == "failed":
                err_type = "runtime_error"
                err_msg = "nonzero_exit"

    dur_ms = int((time.time() - start) * 1000)

    # Persist completion
    finished = _now()
    for r in exec_reqs[::-1]:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = status
            r["exit_code"] = run.get("exit_code")
            r["stdout"] = run.get("stdout")
            r["stderr"] = run.get("stderr")
            r["duration_ms"] = dur_ms
            r["error_type"] = err_type
            r["error_message"] = err_msg
            r["finished_at"] = finished
            r["updated_at"] = finished
            # usage_counters: add duration to execution_ms_total upon completion
            ctr["execution_ms_total"] = int(ctr.get("execution_ms_total", 0) or 0) + max(0, dur_ms)
            ctr["updated_at"] = finished
            # update key last_used_at on success
            if status == "succeeded":
                for k in keys:
                    if isinstance(k, dict) and k.get("id") == api_key["id"]:
                        k["last_used_at"] = finished
                        k["updated_at"] = finished
                        break
            row = r
            break

    _save("api_keys.json", keys)
    _save("usage_counters.json", counters)
    _save("execution_requests.json", exec_reqs)

    return {
        "execution_request": row,
        "result": {
            "exitCode": row.get("exit_code"),
            "stdout": row.get("stdout") or "",
            "stderr": row.get("stderr") or "",
            "status": row.get("status"),
            "durationMs": row.get("duration_ms")
        },
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

