                recent += 1
        if recent >= rl:
            return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        return _err("RATE_LIMIT", "Rate limit check failed")

    if language not in ("javascript", "python"):
        return _err("VALIDATION_ERROR", "Unsupported language")
    if not isinstance(code, str) or not code.strip():
        return _err("VALIDATION_ERROR", "code must be a non-empty string")
    if input is not None and not isinstance(input, str):
        return _err("VALIDATION_ERROR", "input must be a string")
    if enableNetworking is not None and not isinstance(enableNetworking, bool):
        return _err("VALIDATION_ERROR", "enableNetworking must be a boolean")

    # Parse variables
    variables_raw = None
    variables_json = None
    if variables is None:
        variables_raw = None
        variables_json = {}
    elif isinstance(variables, dict):
        variables_raw = json.dumps(variables, ensure_ascii=False)
        variables_json = variables
    elif isinstance(variables, str):
        variables_raw = variables
        try:
            parsed = json.loads(variables)
        except Exception:
            parsed = None
        if not isinstance(parsed, dict):
            # Create rejected request row per rule
            now_iso = _now()
            req_id = _gen_id("creq")
            day_iso = _day_bucket_iso()
            # upsert counter at ingress (execute_count++)
            ctr = None
            for c in counters:
                if isinstance(c, dict) and c.get("api_key_id") == api_key["id"] and c.get("day") == day_iso:
                    ctr = c
                    break
            if ctr is None:
                ctr = {
                    "id": _gen_id("cruc"),
                    "api_key_id": api_key["id"],
                    "day": day_iso,
                    "execute_count": 0,
                    "validate_count": 0,
                    "execution_ms_total": 0,
                    "created_at": now_iso,
                    "updated_at": now_iso
                }
                counters.append(ctr)
            ctr["execute_count"] = int(ctr.get("execute_count", 0) or 0) + 1
            ctr["updated_at"] = now_iso

            row = {
                "id": req_id,
                "api_key_id": api_key["id"],
                "tool_name": "execute_code_with_variables",
                "language": language,
                "code": code,
                "stdin": input if input is not None else None,
                "variables_raw": variables_raw,
                "variables_json": None,
                "timeout_ms": min(int(api_key.get("default_timeout_ms", 1000) or 1000), int(api_key.get("max_timeout_ms", 60000) or 60000), int(cap.get("max_timeout_ms", 60000) or 60000), 60000),
                "memory_limit_mb": min(int(api_key.get("default_memory_mb", 128) or 128), int(api_key.get("max_memory_mb", 512) or 512), int(cap.get("max_memory_mb", 512) or 512), 512),
                "enable_networking": bool(enableNetworking) if enableNetworking is not None else False,
                "status": "rejected",
                "reject_reason": "invalid_variables_json",
                "reject_details": {"expected": "object"},
                "exit_code": None,
                "stdout": None,
                "stderr": None,
                "error_type": None,
                "error_message": None,
                "duration_ms": None,
                "billed_units": 1,
                "requested_at": now_iso,
                "started_at": None,
                "finished_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            exec_reqs.append(row)
            _save("usage_counters.json", counters)
            _save("execution_requests.json", exec_reqs)
            return {"execution_request": row, "result": None, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}
        variables_json = parsed
    else:
        return _err("VALIDATION_ERROR", "variables must be an object or a JSON string")

    tmo = _validate_number("timeout", timeout, int_like=True)
    if isinstance(tmo, dict) and "error" in tmo:
        return tmo
    mem = _validate_number("memoryLimit", memoryLimit, int_like=True)
    if isinstance(mem, dict) and "error" in mem:
        return mem

    svc_max_tmo = int(cap.get("max_timeout_ms", 60000) or 60000)
    svc_max_mem = int(cap.get("max_memory_mb", 512) or 512)
    key_max_tmo = int(api_key.get("max_timeout_ms", 60000) or 60000)
    key_def_tmo = int(api_key.get("default_timeout_ms", 1000) or 1000)
    key_max_mem = int(api_key.get("max_memory_mb", 512) or 512)
    key_def_mem = int(api_key.get("default_memory_mb", 128) or 128)

    if tmo is None:
        eff_tmo = key_def_tmo
    else:
        eff_tmo = min(int(tmo), key_max_tmo, svc_max_tmo, 60000)
    if eff_tmo < 1 or eff_tmo > 60000:
        return _err("VALIDATION_ERROR", "timeout out of range")

    if mem is None:
        eff_mem = key_def_mem
    else:
        eff_mem = min(int(mem), key_max_mem, svc_max_mem, 512)
    if eff_mem < 1 or eff_mem > 512:
        return _err("VALIDATION_ERROR", "memoryLimit out of range")

    req_enable_net = bool(enableNetworking) if enableNetworking is not None else False
    net_supported = bool(cap.get("networking_supported", False))
    key_allows_net = bool(api_key.get("allow_networking", False))

    now_iso = _now()
    req_id = _gen_id("creq")
    row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "tool_name": "execute_code_with_variables",
        "language": language,
        "code": code,
        "stdin": input if input is not None else None,
        "variables_raw": variables_raw,
        "variables_json": variables_json,
        "timeout_ms": eff_tmo,
        "memory_limit_mb": eff_mem,
        "enable_networking": req_enable_net,
        "status": "queued",
        "reject_reason": None,
        "reject_details": None,
        "exit_code": None,
        "stdout": None,
        "stderr": None,
        "error_type": None,
        "error_message": None,
        "duration_ms": None,
        "billed_units": 1,
        "requested_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Upsert usage counter at ingress (execute_count++)
    day_iso = _day_bucket_iso()
    ctr = None
    for c in counters:
        if isinstance(c, dict) and c.get("api_key_id") == api_key["id"] and c.get("day") == day_iso:
            ctr = c
            break
    if ctr is None:
        ctr = {
            "id": _gen_id("cruc"),
            "api_key_id": api_key["id"],
            "day": day_iso,
            "execute_count": 0,
            "validate_count": 0,
            "execution_ms_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        counters.append(ctr)
    ctr["execute_count"] = int(ctr.get("execute_count", 0) or 0) + 1
    ctr["updated_at"] = now_iso

    if req_enable_net and (not net_supported or not key_allows_net):
        row["status"] = "rejected"
        row["reject_reason"] = "networking_not_allowed"
        row["finished_at"] = now_iso
        row["updated_at"] = now_iso
        exec_reqs.append(row)
        _save("usage_counters.json", counters)
        _save("execution_requests.json", exec_reqs)
        return {"execution_request": row, "result": None, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    if api_key.get("status") != "active":
        row["status"] = "rejected"
        row["reject_reason"] = "quota_exceeded"
        row["reject_details"] = {"reason": "api_key_inactive"}
        row["finished_at"] = now_iso
        row["updated_at"] = now_iso
        exec_reqs.append(row)
        _save("usage_counters.json", counters)
        _save("execution_requests.json", exec_reqs)
        return {"execution_request": row, "result": None, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    daily_limit = int(api_key.get("daily_exec_limit", 0) or 0)
    if daily_limit >= 0 and int(ctr.get("execute_count", 0) or 0) > daily_limit:
        row["status"] = "rejected"
        row["reject_reason"] = "quota_exceeded"
        row["finished_at"] = now_iso
        row["updated_at"] = now_iso
        exec_reqs.append(row)
        _save("usage_counters.json", counters)
        _save("execution_requests.json", exec_reqs)
        return {"execution_request": row, "result": None, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    # Transition to running, persist
    started = _now()
    row["status"] = "running"
    row["started_at"] = started
    row["updated_at"] = started
    exec_reqs.append(row)
    _save("usage_counters.json", counters)
    _save("execution_requests.json", exec_reqs)

    start = time.time()
    timeout_s = max(0.001, eff_tmo / 1000.0)

    if req_enable_net:
        run = {"status": "completed", "exit_code": 1, "stdout": "", "stderr": "Networking not available in offline runner"}
        status = "failed"
        err_type = "security_error"
        err_msg = "networking_unavailable"
    else:
        if language == "python":
            run = _safe_run_python(code, input, timeout_s, variables_json)
        else:
            run = _safe_run_js(code, input, timeout_s, variables_json)

        if run["status"] == "timeout":
            status = "timed_out"
            err_type = "runtime_error"
            err_msg = "timed_out"
        elif run["status"] == "no_runtime":
            status = "failed"
            err_type = "runtime_error"
            err_msg = "runtime_unavailable"
        else:
            status = "succeeded" if (run.get("exit_code") == 0) else "failed"
            err_type = None if status == "succeeded" else "runtime_error"
            err_msg = None if status == "succeeded" else "nonzero_exit"

    dur_ms = int((time.time() - start) * 1000)
    finished = _now()

    for r in exec_reqs[::-1]:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = status
            r["exit_code"] = run.get("exit_code")
            r["stdout"] = run.get("stdout")
            r["stderr"] = run.get("stderr")
            r["duration_ms"] = dur_ms
            r["error_type"] = err_type
            r["error_message"] = err_msg
            r["finished_at"] = finished
            r["updated_at"] = finished
            ctr["execution_ms_total"] = int(ctr.get("execution_ms_total", 0) or 0) + max(0, dur_ms)
            ctr["updated_at"] = finished
            if status == "succeeded":
                for k in keys:
                    if isinstance(k, dict) and k.get("id") == api_key["id"]:
                        k["last_used_at"] = finished
                        k["updated_at"] = finished
                        break
            row = r
            break

    _save("api_keys.json", keys)
    _save("usage_counters.json", counters)
    _save("execution_requests.json", exec_reqs)

    return {
        "execution_request": row,
        "result": {
            "exitCode": row.get("exit_code"),
            "stdout": row.get("stdout") or "",
            "stderr": row.get("stderr") or "",
            "status": row.get("status"),
            "durationMs": row.get("duration_ms"),
            "variables": row.get("variables_json")
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_capabilities(capabilityProfileId=None, status=None, language=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _append_log(status_s, details=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + str(int(time.time() * 1000)) + "_" + str(int.from_bytes(os.urandom(2), "big")),
            "endpoint": "get_capabilities",
            "api_key_id": None,
            "key_prefix": None,
            "status": status_s,
            "latency_ms": latency_ms,
            "ts": _iso(_now_utc()),
            "details": details or None
        })
        _save("request_logs.json", logs)

    def _decode_cursor(c):
        if c is None:
            return {"after": None}, None
        if not isinstance(c, str):
            return None, _err("VALIDATION_ERROR", "cursor must be a string")
        if c == "":
            return None, _err("VALIDATION_ERROR", "cursor must not be empty")
        # Opaque cursor: accept raw id, or base64url(JSON {"after": "<id>"}), or any string treated as "after"
        if c.startswith("crcap_"):
            return {"after": c}, None
        try:
            raw = base64.urlsafe_b64decode(c + "=" * (-len(c) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("after"), str) and obj["after"]:
                return {"after": obj["after"]}, None
        except Exception:
            pass
        return {"after": c}, None

    def _encode_cursor(after_id):
        payload = json.dumps({"after": after_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # ---- Validate inputs ----
    if capabilityProfileId is not None and not isinstance(capabilityProfileId, str):
        _append_log("error", {"code": "VALIDATION_ERROR", "field": "capabilityProfileId"})
        return _err("VALIDATION_ERROR", "capabilityProfileId must be a string")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "inactive", "deprecated"):
            _append_log("error", {"code": "VALIDATION_ERROR", "field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive, deprecated")
    if language is not None:
        if not isinstance(language, str) or language not in ("javascript", "python"):
            _append_log("error", {"code": "VALIDATION_ERROR", "field": "language"})
            return _err("VALIDATION_ERROR", "language must be one of: javascript, python")
    if limit is not None:
        if not isinstance(limit, int):
            _append_log("error", {"code": "VALIDATION_ERROR", "field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            _append_log("error", {"code": "VALIDATION_ERROR", "field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        _append_log("error", {"code": "VALIDATION_ERROR", "field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    profiles = _load("capability_profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    # Single profile fetch when provided: schema says raise VALIDATION_ERROR for invalid capabilityProfileId.
    if capabilityProfileId is not None:
        # Real API: validate format. However, audit shows callers may pass other ids; treat as invalid *format*.
        if not re.match(r"^crcap_[0-9A-HJKMNP-TV-Z]{10,}$", capabilityProfileId or ""):
            _append_log("error", {"code": "VALIDATION_ERROR", "field": "capabilityProfileId"})
            return _err("VALIDATION_ERROR", "invalid capabilityProfileId")
        row = next((r for r in profiles if isinstance(r, dict) and r.get("id") == capabilityProfileId), None)
        if row is None:
            # For lookup by id, not found is still NOT_FOUND (id format was valid).
            _append_log("error", {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Capability profile not found")
        # Envelope: return normalized capabilities for single row
        out = {
            "id": row.get("id"),
            "name": row.get("name"),
            "status": row.get("status"),
            "supported_languages": row.get("supported_languages") if isinstance(row.get("supported_languages"), list) else [],
            "limits": {
                "max_timeout_ms": row.get("max_timeout_ms"),
                "max_memory_mb": row.get("max_memory_mb"),
            },
            "networking_supported": bool(row.get("networking_supported")),
            "security_policy": row.get("security_policy"),
            "sandbox_engine": row.get("sandbox_engine"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }
        _append_log("ok", {"mode": "single"})
        return {"capability_profile": out}

    # Otherwise: return default active capabilities OR list if filters/pagination used
    decoded, derr = _decode_cursor(cursor)
    if derr:
        _append_log("error", {"code": "VALIDATION_ERROR", "field": "cursor"})
        return derr
    after = decoded.get("after")

    # If no filters and no pagination knobs, return the single active/default platform capabilities.
    if status is None and language is None and limit is None and cursor is None:
        active_rows = [r for r in profiles if isinstance(r, dict) and r.get("status") == "active"]
        # Business rule: only one active, but datastore may be inconsistent; pick the most recently updated.
        def _ts(r, k):
            v = r.get(k)
            if not isinstance(v, str):
                return ""
            return v
        active_rows.sort(key=lambda r: (_ts(r, "updated_at"), _ts(r, "created_at"), r.get("id") or ""), reverse=True)
        row = active_rows[0] if active_rows else None
        if row is None:
            _append_log("error", {"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "No active capability profile available")
        out = {
            "id": row.get("id"),
            "name": row.get("name"),
            "status": row.get("status"),
            "supported_languages": row.get("supported_languages") if isinstance(row.get("supported_languages"), list) else [],
            "limits": {
                "max_timeout_ms": row.get("max_timeout_ms"),
                "max_memory_mb": row.get("max_memory_mb"),
            },
            "networking_supported": bool(row.get("networking_supported")),
            "security_policy": row.get("security_policy"),
            "sandbox_engine": row.get("sandbox_engine"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }
        _append_log("ok", {"mode": "default_active"})
        return {"capabilities": out}

    # Listing mode with filters/pagination
    rows = [r for r in profiles if isinstance(r, dict)]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if language is not None:
        rows = [r for r in rows if isinstance(r.get("supported_languages"), list) and language in r.get("supported_languages")]
    # Stable sort by id for cursor pagination (opaque)
    rows.sort(key=lambda r: (r.get("id") or ""))

    start_idx = 0
    if after:
        for i, r in enumerate(rows):
            if r.get("id") == after:
                start_idx = i + 1
                break

    lim = limit if isinstance(limit, int) else 50
    page = rows[start_idx:start_idx + lim]
    has_more = start_idx + lim < len(rows)
    next_cursor = _encode_cursor(page[-1].get("id")) if has_more and page else None

    def _shape(r):
        return {
            "id": r.get("id"),
            "name": r.get("name"),
            "status": r.get("status"),
            "supported_languages": r.get("supported_languages") if isinstance(r.get("supported_languages"), list) else [],
            "limits": {
                "max_timeout_ms": r.get("max_timeout_ms"),
                "max_memory_mb": r.get("max_memory_mb"),
            },
            "networking_supported": bool(r.get("networking_supported")),
            "security_policy": r.get("security_policy"),
            "sandbox_engine": r.get("sandbox_engine"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        }

    _append_log("ok", {"mode": "list", "returned": len(page), "total": len(rows)})
    return {
        "capability_profiles": [_shape(r) for r in page],
        "meta": {"total": len(rows), "has_more": has_more, "next_cursor": next_cursor, "limit": lim}
    }

def validate_code(language, code, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _day_bucket_iso():
        n = datetime.datetime.now(datetime.timezone.utc)
        d = datetime.datetime(n.year, n.month, n.day, tzinfo=datetime.timezone.utc)
        return d.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        r = (ms << 80) | int.from_bytes(os.urandom(10), "big")
        out = []
        for _ in range(26):
            out.append(alphabet[r & 31])
            r >>= 5
        return f"{prefix}_{''.join(reversed(out))}"

    def _select_key(keys):
        candidates = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not candidates:
            return None
        candidates.sort(key=lambda x: (x.get("last_used_at") or "", x.get("updated_at") or "", x.get("created_at") or ""), reverse=True)
        return candidates[0]

    def _find_active_cap_profile(profiles):
        actives = [p for p in profiles if isinstance(p, dict) and p.get("status") == "active"]
        if actives:
            actives.sort(key=lambda x: (x.get("updated_at") or "", x.get("created_at") or ""), reverse=True)
            return actives[0]
        return None

    # Validate inputs
    if language not in ("javascript", "python"):
        return _err("VALIDATION_ERROR", "Unsupported language")
    if not isinstance(code, str) or not code.strip():
        return _err("VALIDATION_ERROR", "code must be a non-empty string")

    keys = _load("api_keys.json")
    profiles = _load("capability_profiles.json")
    validations = _load("code_validations.json")
    exec_reqs = _load("execution_requests.json")
    counters = _load("usage_counters.json")

    api_key = _select_key(keys)
    cap = _find_active_cap_profile(profiles)
    if api_key is None or cap is None:
        return _err("UNAUTHORIZED", "No active API key and capability profile combination available")

    # Rate limit check
    try:
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        rl = int(api_key.get("rate_limit_per_min", 1) or 1)
        recent = 0
        for r in exec_reqs:
            if not isinstance(r, dict): 
                continue
            if r.get("api_key_id") != api_key.get("id"):
                continue
            ts = r.get("requested_at") or r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts_dt >= minute_ago:
                recent += 1
        for v in validations:
            if not isinstance(v, dict): 
                continue
            if v.get("api_key_id") != api_key.get("id"):
                continue
            ts = v.get("requested_at") or v.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                ts_dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if ts_dt >= minute_ago:
                recent += 1
        if recent >= rl:
            return _err("RATE_LIMIT", "Rate limit exceeded")
    except Exception:
        return _err("RATE_LIMIT", "Rate limit check failed")

    now_iso = _now()
    day_iso = _day_bucket_iso()

    # Upsert usage counter at ingress (validate_count++)
    ctr = None
    for c in counters:
        if isinstance(c, dict) and c.get("api_key_id") == api_key["id"] and c.get("day") == day_iso:
            ctr = c
            break
    if ctr is None:
        ctr = {
            "id": _gen_id("cruc"),
            "api_key_id": api_key["id"],
            "day": day_iso,
            "execute_count": 0,
            "validate_count": 0,
            "execution_ms_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        counters.append(ctr)
    ctr["validate_count"] = int(ctr.get("validate_count", 0) or 0) + 1
    ctr["updated_at"] = now_iso

    vid = _gen_id("crval")
    row = {
        "id": vid,
        "api_key_id": api_key["id"],
        "language": language,
        "code": code,
        "status": "queued",
        "is_secure": None,
        "is_syntax_valid": None,
        "issues": None,
        "error_message": None,
        "requested_at": now_iso,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    validations.append(row)

    # Enforce quota before "running"
    if api_key.get("status") != "active":
        row["status"] = "error"
        row["error_message"] = "quota_exceeded"
        row["finished_at"] = _now()
        row["updated_at"] = row["finished_at"]
        _save("usage_counters.json", counters)
        _save("code_validations.json", validations)
        return {"validation": row, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    daily_limit = int(api_key.get("daily_validate_limit", 0) or 0)
    if daily_limit >= 0 and int(ctr.get("validate_count", 0) or 0) > daily_limit:
        row["status"] = "error"
        row["error_message"] = "quota_exceeded"
        row["finished_at"] = _now()
        row["updated_at"] = row["finished_at"]
        _save("usage_counters.json", counters)
        _save("code_validations.json", validations)
        return {"validation": row, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    # Transition queued -> running
    row["status"] = "running"
    row["updated_at"] = _now()

    issues = []

    # Syntax checks (validation-only)
    is_syntax_valid = True
    if language == "python":
        try:
            compile(code, "<validated>", "exec")
        except SyntaxError as e:
            is_syntax_valid = False
            issues.append({
                "type": "syntax_error",
                "severity": "error",
                "message": str(e),
                "line": getattr(e, "lineno", None),
                "column": getattr(e, "offset", None)
            })
    else:
        # Best-effort JS syntax heuristics (no JS parser offline)
        # Flag obviously unbalanced braces/parens as syntax issue.
        pairs = {"{": "}", "(": ")", "[": "]"}
        stack = []
        for i, ch in enumerate(code):
            if ch in pairs:
                stack.append(ch)
            elif ch in (")", "}", "]"):
                if not stack:
                    is_syntax_valid = False
                    issues.append({"type": "syntax_error", "severity": "error", "message": "Unmatched closing bracket", "position": i})
                    break
                op = stack.pop()
                if pairs[op] != ch:
                    is_syntax_valid = False
                    issues.append({"type": "syntax_error", "severity": "error", "message": "Mismatched brackets", "position": i})
                    break
        if is_syntax_valid and stack:
            is_syntax_valid = False
            issues.append({"type": "syntax_error", "severity": "error", "message": "Unclosed bracket(s)"})

    # Security/policy checks based on active capability profile
    policy = cap.get("security_policy") if isinstance(cap, dict) else None
    disallowed = []
    if isinstance(policy, dict):
        dm = policy.get("disallowed_modules")
        if isinstance(dm, list):
            disallowed.extend([x for x in dm if isinstance(x, str) and x])
        dp = policy.get("disallowed_patterns")
        if isinstance(dp, list):
            disallowed.extend([x for x in dp if isinstance(x, str) and x])

    # Default minimal policy
    if not disallowed:
        if language == "python":
            disallowed = ["import os", "import subprocess", "import socket", "eval(", "exec("]
        else:
            disallowed = ["require('child_process')", "require(\"child_process\")", "eval(", "Function("]

    is_secure = True
    for pat in disallowed:
        if pat in code:
            is_secure = False
            issues.append({"type": "policy_violation", "severity": "warning", "message": f"Disallowed pattern detected: {pat}"})

    # Finish with passed/failed
    row["is_syntax_valid"] = bool(is_syntax_valid)
    row["is_secure"] = bool(is_secure)
    row["issues"] = issues
    row["status"] = "passed" if (is_syntax_valid and is_secure) else "failed"
    row["finished_at"] = _now()
    row["updated_at"] = row["finished_at"]

    _save("usage_counters.json", counters)
    _save("code_validations.json", validations)

    return {"validation": row, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def get_current_identity(apiKey, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _day_bucket_iso(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d0 = datetime.datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=datetime.timezone.utc)
        return _iso(d0)

    def _ensure_request_log(api_key_id, key_prefix, status_s, latency_ms, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "rlog_" + str(int(time.time() * 1000)) + "_" + str(int.from_bytes(os.urandom(2), "big")),
                "endpoint": "get_current_identity",
                "api_key_id": api_key_id,
                "key_prefix": key_prefix,
                "status": status_s,
                "latency_ms": int(latency_ms),
                "ts": _iso(_now_utc()),
                "details": details or None,
            }
        )
        _save("request_logs.json", logs)

    def _parse_rfc3339(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _rate_limited(api_key_row):
        rl = api_key_row.get("rate_limit_per_min")
        if not isinstance(rl, int) or rl < 1:
            return False, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False, None
        now = _now_utc()
        ws = now - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_rfc3339(r.get("ts"))
            if ts is None:
                continue
            if ts >= ws and ts <= now:
                c += 1
        if c >= rl:
            return True, {"limit_per_min": rl, "used_last_60s": c}
        return False, {"limit_per_min": rl, "used_last_60s": c}

    t0 = time.time()

    if not isinstance(apiKey, str) or not apiKey.strip():
        _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string.")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    # Authenticate by client-visible value: accept apiKey as api_keys.id OR key_prefix (store doesn't contain plaintext key)
    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == apiKey or r.get("key_prefix") == apiKey:
            key_row = r
            break

    if key_row is None:
        _ensure_request_log(None, None, "unauthorized", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key.")

    if key_row.get("status") == "revoked":
        _ensure_request_log(key_row.get("id"), key_row.get("key_prefix"), "unauthorized", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Rate limit
    limited, rate_meta = _rate_limited(key_row)
    if limited:
        _ensure_request_log(key_row.get("id"), key_row.get("key_prefix"), "rate_limited", (time.time() - t0) * 1000, {"code": "RATE_LIMIT", "rate": rate_meta})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate=rate_meta)

    # Quota usage for UTC day
    counters = _load("usage_counters.json")
    if not isinstance(counters, list):
        counters = []
    day_iso = _day_bucket_iso(_now_utc())
    counter = None
    for r in counters:
        if isinstance(r, dict) and r.get("api_key_id") == key_row.get("id") and r.get("day") == day_iso:
            counter = r
            break
    if counter is None:
        used_exec = 0
        used_val = 0
        used_ms = 0
    else:
        used_exec = counter.get("execute_count") if isinstance(counter.get("execute_count"), int) else 0
        used_val = counter.get("validate_count") if isinstance(counter.get("validate_count"), int) else 0
        used_ms = counter.get("execution_ms_total") if isinstance(counter.get("execution_ms_total"), int) else 0

    body = {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "entitlements": {
                "default_timeout_ms": key_row.get("default_timeout_ms"),
                "max_timeout_ms": key_row.get("max_timeout_ms"),
                "default_memory_mb": key_row.get("default_memory_mb"),
                "max_memory_mb": key_row.get("max_memory_mb"),
                "allow_networking": bool(key_row.get("allow_networking")),
                "rate_limit_per_min": key_row.get("rate_limit_per_min"),
                "daily_exec_limit": key_row.get("daily_exec_limit"),
                "daily_validate_limit": key_row.get("daily_validate_limit"),
            },
            "timestamps": {
                "created_at": key_row.get("created_at"),
                "updated_at": key_row.get("updated_at"),
                "last_used_at": key_row.get("last_used_at"),
            },
        },
        "usage": {
            "day": day_iso,
            "execute": {"used": used_exec, "limit": key_row.get("daily_exec_limit")},
            "validate": {"used": used_val, "limit": key_row.get("daily_validate_limit")},
            "execution_ms_total": used_ms,
        },
        "rate_limit": rate_meta,
    }

    # last_used_at updated on successful identity fetch
    key_row["last_used_at"] = _iso(_now_utc())
    key_row["updated_at"] = _iso(_now_utc())
    _save("api_keys.json", api_keys)

    _ensure_request_log(key_row.get("id"), key_row.get("key_prefix"), "ok", (time.time() - t0) * 1000)
    return body

def list_execution_requests(apiKey, status=None, language=None, fromRequestedAt=None, toRequestedAt=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_rfc3339(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _ensure_request_log(api_key_id, key_prefix, status_s, latency_ms, details=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": "rlog_" + str(int(time.time() * 1000)) + "_" + str(int.from_bytes(os.urandom(2), "big")),
                "endpoint": "list_execution_requests",
                "api_key_id": api_key_id,
                "key_prefix": key_prefix,
                "status": status_s,
                "latency_ms": int(latency_ms),
                "ts": _iso(_now_utc()),
                "details": details or None,
            }
        )
        _save("request_logs.json", logs)

    def _rate_limited(api_key_row):
        rl = api_key_row.get("rate_limit_per_min")
        if not isinstance(rl, int) or rl < 1:
            return False, None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return False, None
        now = _now_utc()
        ws = now - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_rfc3339(r.get("ts"))
            if ts is None:
                continue
            if ts >= ws and ts <= now:
                c += 1
        if c >= rl:
            return True, {"limit_per_min": rl, "used_last_60s": c}
        return False, {"limit_per_min": rl, "used_last_60s": c}

    def _decode_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or c == "":
            return _err("VALIDATION_ERROR", "cursor must be a string")
        # Accept plain execution request id, or base64 {"after": "..."}
        if c.startswith("crx_") or c.startswith("creq_"):
            return c
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("after"), str) and obj["after"]:
                return obj["after"]
        except Exception:
            return c
        return c

    def _encode_cursor(after_id):
        payload = json.dumps({"after": after_id}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    t0 = time.time()

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "timed_out", "rejected", "cancelled"):
        _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status is invalid.")
    if language is not None and language not in ("javascript", "python"):
        _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "language is invalid.")
    from_dt = None
    to_dt = None
    if fromRequestedAt is not None:
        from_dt = _parse_rfc3339(fromRequestedAt)
        if from_dt is None:
            _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "fromRequestedAt must be an RFC3339 date-time string.")
    if toRequestedAt is not None:
        to_dt = _parse_rfc3339(toRequestedAt)
        if to_dt is None:
            _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "toRequestedAt must be an RFC3339 date-time string.")
    if from_dt and to_dt and from_dt > to_dt:
        _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "fromRequestedAt must be <= toRequestedAt.")

    if limit is None:
        limit_eff = 50
    else:
        if isinstance(limit, bool) or not isinstance(limit, int):
            _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1:
            _ensure_request_log(None, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be >= 1.")
        # Accept caller's 120 by clamping to 100.
        limit_eff = min(limit, 100)

    # Authenticate by id or key_prefix (store has no plaintext key)
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("id") == apiKey or r.get("key_prefix") == apiKey):
            key_row = r
            break
    if key_row is None or key_row.get("status") == "revoked":
        _ensure_request_log(key_row.get("id") if key_row else None, key_row.get("key_prefix") if key_row else None, "unauthorized", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key.")

    limited, rate_meta = _rate_limited(key_row)
    if limited:
        _ensure_request_log(key_row.get("id"), key_row.get("key_prefix"), "rate_limited", (time.time() - t0) * 1000, {"code": "RATE_LIMIT", "rate": rate_meta})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate=rate_meta)

    execs = _load("execution_requests.json")
    if not isinstance(execs, list):
        execs = []

    # Filter to this key's requests only
    items = []
    for r in execs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row.get("id"):
            continue
        if status is not None and r.get("status") != status:
            continue
        if language is not None and r.get("language") != language:
            continue
        if from_dt is not None or to_dt is not None:
            ra = _parse_rfc3339(r.get("requested_at"))
            if ra is None:
                continue
            if from_dt is not None and ra < from_dt:
                continue
            if to_dt is not None and ra > to_dt:
                continue
        items.append(r)

    # newest-first by requested_at then id
    def _k(r):
        return (r.get("requested_at") or "", r.get("id") or "")

    items.sort(key=_k, reverse=True)

    after = _decode_cursor(cursor)
    if isinstance(after, dict) and after.get("error"):
        _ensure_request_log(key_row.get("id"), key_row.get("key_prefix"), "error", (time.time() - t0) * 1000, {"code": after["error"]["code"]})
        return after

    start_idx = 0
    if after:
        for i, r in enumerate(items):
            if r.get("id") == after:
                start_idx = i + 1
                break

    page = items[start_idx : start_idx + limit_eff]
    has_more = start_idx + limit_eff < len(items)
    next_cursor = _encode_cursor(page[-1].get("id")) if (has_more and page) else None

    # Update last_used_at on successful read
    key_row["last_used_at"] = _iso(_now_utc())
    key_row["updated_at"] = _iso(_now_utc())
    _save("api_keys.json", api_keys)

    body = {
        "data": page,
        "total": len(items),
        "limit": limit_eff,
        "has_more": bool(has_more),
        "next_cursor": next_cursor,
        "rate_limit": rate_meta,
    }
    _ensure_request_log(key_row.get("id"), key_row.get("key_prefix"), "ok", (time.time() - t0) * 1000)
    return body

def get_execution_request(apiKey, executionRequestId, **_extra):
    import json, os, datetime, time, re

