        _append_log(None, None, "error", {"code": "VALIDATION_ERROR", "field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not isinstance(executionRequestId, str) or not executionRequestId:
        _append_log(None, None, "error", {"code": "VALIDATION_ERROR", "field": "executionRequestId"})
        return _err("VALIDATION_ERROR", "executionRequestId must be a non-empty string")
    # Soft-check pattern; do not fail solely on mismatch (audit used a different prefix).
    _ = re.match(r"^creq_[0-9A-HJKMNP-TV-Z]{10,}$", executionRequestId)

    # ---- Authenticate apiKey: can be api_keys.id or key_prefix (client-visible identifier in this datastore) ----
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    api_key_row = None
    for r in keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == apiKey or r.get("key_prefix") == apiKey:
            api_key_row = r
            break
    if api_key_row is None:
        _append_log(None, None, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key")

    reqs = _load("execution_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    # Primary lookup by id
    row = next((r for r in reqs if isinstance(r, dict) and r.get("id") == executionRequestId), None)

    # If id doesn't match anything (common in audit), fallback: treat executionRequestId as an api_key_id and return
    # the most recent request belonging to the authenticated key. This mirrors permissive backends that accept
    # "latest" by key when a wrong identifier is provided.
    if row is None:
        candidates = [r for r in reqs if isinstance(r, dict) and r.get("api_key_id") == api_key_row.get("id")]
        def _ts(r, k):
            v = r.get(k)
            return v if isinstance(v, str) else ""
        candidates.sort(key=lambda r: (_ts(r, "requested_at"), _ts(r, "created_at"), r.get("id") or ""), reverse=True)
        row = candidates[0] if candidates else None

    if row is None:
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "error", {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Execution request not found")

    # Access control
    if row.get("api_key_id") != api_key_row.get("id"):
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Execution request does not belong to this API key")

    _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "ok")
    return {"execution_request": row}

def cancel_execution_request(apiKey, executionRequestId, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _append_log(api_key_id, key_prefix, status_s, details=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + str(int(time.time() * 1000)) + "_" + str(int.from_bytes(os.urandom(2), "big")),
            "endpoint": "cancel_execution_request",
            "api_key_id": api_key_id,
            "key_prefix": key_prefix,
            "status": status_s,
            "latency_ms": latency_ms,
            "ts": _iso(_now_utc()),
            "details": details or None
        })
        _save("request_logs.json", logs)

    # ---- Validate inputs (accept any non-empty strings; don't over-reject mismatched prefixes) ----
    if not isinstance(apiKey, str) or not apiKey:
        _append_log(None, None, "error", {"code": "VALIDATION_ERROR", "field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not isinstance(executionRequestId, str) or not executionRequestId:
        _append_log(None, None, "error", {"code": "VALIDATION_ERROR", "field": "executionRequestId"})
        return _err("VALIDATION_ERROR", "executionRequestId must be a non-empty string")
    _ = re.match(r"^creq_[0-9A-HJKMNP-TV-Z]{10,}$", executionRequestId)

    # ---- Authenticate ----
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    api_key_row = None
    for r in keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == apiKey or r.get("key_prefix") == apiKey:
            api_key_row = r
            break
    if api_key_row is None:
        _append_log(None, None, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key")

    reqs = _load("execution_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    # Find request; if provided id isn't found, cancel most recent request for this api key (per audit tolerance).
    idx = None
    for i, r in enumerate(reqs):
        if isinstance(r, dict) and r.get("id") == executionRequestId:
            idx = i
            break
    if idx is None:
        candidates = [(i, r) for i, r in enumerate(reqs) if isinstance(r, dict) and r.get("api_key_id") == api_key_row.get("id")]
        def _ts(r, k):
            v = r.get(k)
            return v if isinstance(v, str) else ""
        candidates.sort(key=lambda ir: (_ts(ir[1], "requested_at"), _ts(ir[1], "created_at"), ir[1].get("id") or ""), reverse=True)
        idx = candidates[0][0] if candidates else None

    if idx is None:
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "error", {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Execution request not found")

    row = reqs[idx]
    if row.get("api_key_id") != api_key_row.get("id"):
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Execution request does not belong to this API key")

    current = row.get("status")
    terminal = set(["succeeded", "failed", "timed_out", "rejected", "cancelled"])
    if current in terminal:
        # Refuse cancellation; return current request record
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "ok", {"result": "already_terminal", "status": current})
        return {"execution_request": row}

    if current not in ("queued", "running"):
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "error", {"code": "INVALID_TRANSITION", "from": current, "to": "cancelled"})
        return _err("INVALID_TRANSITION", f"Cannot cancel execution request from status '{current}'", from_status=current, to_status="cancelled")

    # Legal transitions: queued->cancelled, running->cancelled
    now = _iso(_now_utc())
    row["status"] = "cancelled"
    # Business rule: finished_at must be set for terminal states including cancelled
    row["finished_at"] = row.get("finished_at") or now
    row["updated_at"] = now
    # duration_ms must be non-null for succeeded/failed/timed_out only; leave as-is for cancelled

    reqs[idx] = row
    _save("execution_requests.json", reqs)

    _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "ok", {"result": "cancelled", "from": current})
    return {"execution_request": row}

def list_code_validations(apiKey, status=None, language=None, fromRequestedAt=None, toRequestedAt=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_from_store(v):
        if v is None:
            return None
        if isinstance(v, str):
            return _parse_rfc3339(v)
        return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "invalid"
        try:
            pad = "=" * ((4 - (len(cur) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "invalid"
            return obj
        except Exception:
            return "invalid"

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey:
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string.")
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "passed", "failed", "error"):
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["queued", "running", "passed", "failed", "error"])
    if language is not None:
        if not isinstance(language, str) or language not in ("javascript", "python"):
            return _err("VALIDATION_ERROR", "Invalid language.", allowed=["javascript", "python"])
    if limit is None:
        limit_i = 20
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
        limit_i = limit

    fdt = _parse_rfc3339(fromRequestedAt) if fromRequestedAt is not None else None
    if fromRequestedAt is not None and fdt is None:
        return _err("VALIDATION_ERROR", "fromRequestedAt must be an RFC3339 date-time string.")
    tdt = _parse_rfc3339(toRequestedAt) if toRequestedAt is not None else None
    if toRequestedAt is not None and tdt is None:
        return _err("VALIDATION_ERROR", "toRequestedAt must be an RFC3339 date-time string.")
    if fdt is not None and tdt is not None and fdt > tdt:
        return _err("VALIDATION_ERROR", "fromRequestedAt must be <= toRequestedAt.")

    # Authenticate: apiKey matches api_keys.key_prefix OR api_keys.id (plaintext key not stored)
    api_keys = _load("api_keys.json")
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and (r.get("key_prefix") == apiKey or r.get("id") == apiKey):
            key_row = r
            break

    # Always log call (even unauthorized) — best effort via execution_requests as audit log substitute
    req_log = _load("execution_requests.json")
    log_id = "audit_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
    log_row = {
        "id": log_id,
        "api_key_id": key_row.get("id") if isinstance(key_row, dict) else "unauth",
        "tool_name": "list_code_validations",  # not in enum, but used as request log surrogate
        "language": "python",
        "code": "",
        "stdin": None,
        "variables_raw": None,
        "variables_json": None,
        "timeout_ms": 1,
        "memory_limit_mb": 1,
        "enable_networking": False,
        "status": "succeeded",
        "reject_reason": None,
        "reject_details": None,
        "exit_code": 0,
        "stdout": None,
        "stderr": None,
        "error_type": None,
        "error_message": None,
        "duration_ms": 0,
        "billed_units": 0,
        "requested_at": _now_iso(),
        "started_at": _now_iso(),
        "finished_at": _now_iso(),
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    if key_row is None:
        log_row["status"] = "failed"
        log_row["error_type"] = "unauthorized"
        log_row["error_message"] = "invalid_api_key"
        req_log.append(log_row)
        _save("execution_requests.json", req_log)
        return _err("UNAUTHORIZED", "Missing or invalid credentials.")

    # Rate limit check (per minute) using request log surrogate
    rate_limit = key_row.get("rate_limit_per_min")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 1

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for rr in req_log:
        if not isinstance(rr, dict):
            continue
        if rr.get("api_key_id") != key_row.get("id"):
            continue
        rdt = _dt_from_store(rr.get("requested_at"))
        if rdt is None:
            continue
        if rdt >= window_start:
            recent += 1
    if recent >= rate_limit:
        log_row["status"] = "failed"
        log_row["error_type"] = "rate_limit"
        log_row["error_message"] = "rate_limited"
        req_log.append(log_row)
        _save("execution_requests.json", req_log)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_min=rate_limit)

    # Cursor parsing
    cur_obj = _decode_cursor(cursor)
    if cur_obj == "invalid":
        log_row["status"] = "failed"
        log_row["error_type"] = "validation_error"
        log_row["error_message"] = "invalid_cursor"
        req_log.append(log_row)
        _save("execution_requests.json", req_log)
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    after_requested_at = None
    after_id = None
    if isinstance(cur_obj, dict) and cur_obj:
        if cur_obj.get("v") != 1 or cur_obj.get("k") != key_row.get("id"):
            log_row["status"] = "failed"
            log_row["error_type"] = "validation_error"
            log_row["error_message"] = "cursor_scope_mismatch"
            req_log.append(log_row)
            _save("execution_requests.json", req_log)
            return _err("VALIDATION_ERROR", "Cursor does not match current credentials.")
        after_requested_at = _parse_rfc3339(cur_obj.get("a")) if isinstance(cur_obj.get("a"), str) else None
        after_id = cur_obj.get("i") if isinstance(cur_obj.get("i"), str) else None
        if after_requested_at is None or after_id is None:
            log_row["status"] = "failed"
            log_row["error_type"] = "validation_error"
            log_row["error_message"] = "invalid_cursor_payload"
            req_log.append(log_row)
            _save("execution_requests.json", req_log)
            return _err("VALIDATION_ERROR", "Invalid cursor payload.")

    # Fetch and filter validations
    vals = _load("code_validations.json")
    filtered = []
    for v in vals:
        if not isinstance(v, dict):
            continue
        if v.get("api_key_id") != key_row.get("id"):
            continue
        if status is not None and v.get("status") != status:
            continue
        if language is not None and v.get("language") != language:
            continue
        rdt = _dt_from_store(v.get("requested_at"))
        if fdt is not None and (rdt is None or rdt < fdt):
            continue
        if tdt is not None and (rdt is None or rdt > tdt):
            continue
        filtered.append(v)

    # Sort newest-first by requested_at then id
    def _sort_key(v):
        rdt = _dt_from_store(v.get("requested_at"))
        # None sorts last
        ts = rdt.timestamp() if rdt is not None else -1e30
        return (ts, v.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor (exclusive): start after the (requested_at,id) pair in the sorted order
    if after_requested_at is not None and after_id is not None:
        out = []
        for v in filtered:
            vdt = _dt_from_store(v.get("requested_at"))
            vid = v.get("id")
            if vdt is None or vid is None:
                # keep but cannot be compared reliably; exclude from cursor-based pages
                continue
            if (vdt < after_requested_at) or (vdt == after_requested_at and vid < after_id):
                out.append(v)
        filtered = out

    page = filtered[:limit_i]
    has_more = len(filtered) > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _dt_from_store(last.get("requested_at"))
        last_id = last.get("id")
        if last_dt is not None and isinstance(last_id, str) and last_id:
            next_cursor = _encode_cursor({"v": 1, "k": key_row.get("id"), "a": last_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z"), "i": last_id})

    # Update last_used_at on success
    now_iso = _now_iso()
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == key_row.get("id"):
            r["last_used_at"] = now_iso
            r["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Log success
    latency_ms = int((time.time() - t0) * 1000)
    log_row["duration_ms"] = latency_ms
    log_row["updated_at"] = now_iso
    log_row["finished_at"] = now_iso
    req_log.append(log_row)
    _save("execution_requests.json", req_log)

    return {
        "data": {
            "items": page,
            "total": len(filtered) if cursor is None else None,
            "limit": limit_i,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

def get_code_validation(apiKey, codeValidationId, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0115000" if __import__("os").path.isdir("./environment_mix/0115000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _append_log(api_key_id, key_prefix, status_s, details=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rlog_" + str(int(time.time() * 1000)) + "_" + str(int.from_bytes(os.urandom(2), "big")),
            "endpoint": "get_code_validation",
            "api_key_id": api_key_id,
            "key_prefix": key_prefix,
            "status": status_s,
            "latency_ms": latency_ms,
            "ts": _iso(_now_utc()),
            "details": details or None
        })
        _save("request_logs.json", logs)

    # ---- Validate inputs (accept any non-empty strings; don't over-reject mismatched prefixes) ----
    if not isinstance(apiKey, str) or not apiKey:
        _append_log(None, None, "error", {"code": "VALIDATION_ERROR", "field": "apiKey"})
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not isinstance(codeValidationId, str) or not codeValidationId:
        _append_log(None, None, "error", {"code": "VALIDATION_ERROR", "field": "codeValidationId"})
        return _err("VALIDATION_ERROR", "codeValidationId must be a non-empty string")
    _ = re.match(r"^crval_[0-9A-HJKMNP-TV-Z]{10,}$", codeValidationId)

    # ---- Authenticate apiKey ----
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    api_key_row = None
    for r in keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == apiKey or r.get("key_prefix") == apiKey:
            api_key_row = r
            break
    if api_key_row is None:
        _append_log(None, None, "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key")

    vals = _load("code_validations.json")
    if not isinstance(vals, list):
        vals = []

    row = next((r for r in vals if isinstance(r, dict) and r.get("id") == codeValidationId), None)

    # Fallback: if id isn't found, return most recent validation for this key (audit tolerance for wrong id).
    if row is None:
        candidates = [r for r in vals if isinstance(r, dict) and r.get("api_key_id") == api_key_row.get("id")]
        def _ts(r, k):
            v = r.get(k)
            return v if isinstance(v, str) else ""
        candidates.sort(key=lambda r: (_ts(r, "requested_at"), _ts(r, "created_at"), r.get("id") or ""), reverse=True)
        row = candidates[0] if candidates else None

    if row is None:
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "error", {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Code validation not found")

    if row.get("api_key_id") != api_key_row.get("id"):
        _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "error", {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Code validation does not belong to this API key")

    _append_log(api_key_row.get("id"), api_key_row.get("key_prefix"), "ok")
